import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import {
  ButtonGroupButtonPositions,
  ButtonGroupIconPosition,
  ButtonGroupSize,
  ButtonGroupVariant,
  FormDataEvent,
} from '../../../types';
import { AriaAttributes, extractAriaAttributes } from '../../../utils/a11y-helper';

/**
 * @slot default - default slot for the content of the button-group-button
 */
@Component({
  tag: 'groupui-button-group-button',
  styleUrl: 'button-group-button.scss',
  shadow: { delegatesFocus: true },
})
export class ButtonGroupButton implements ComponentInterface {
  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly inverted: boolean;

  /**
   * enables the button-group-button to grow. The fullwidth property of the groupui-button-group will overwrite this one.
   */
  @Prop({ reflect: true }) readonly samewidth: boolean;

  /**
   * icon to show beside the text e.g. clock-24
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly spaced: boolean;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly size: ButtonGroupSize = 'm';

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly iconOnly: boolean;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly variant: ButtonGroupVariant;

  /**
   *  defines a button as checked
   */
  @Prop({ reflect: true }) readonly checked: boolean = false;

  /**
   * deactivates the button-group-button
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * used to handle forms and identify which button-group-button is selected
   */
  @Prop({ reflect: true }) readonly value: string;

  /**
   * used to be referenced in a form. The name of the groupui-button-group will overwrite this one.
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * internal property to identify the position of the button in the group
   * @internal
   */
  @Prop({ reflect: true }) readonly position: ButtonGroupButtonPositions;

  /**
   * sets focus automatically
   */
  @Prop({ reflect: true }) readonly autofocus: boolean;

  /**
   * sets the position of the icon relative to the text. Orchestrated by the groupui-button-group.
   * @internal
   */
  @Prop({ reflect: true }) readonly iconPosition: ButtonGroupIconPosition;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  @State() buttonTabIndex: number = 0;

  @State() ariaAttributes: AriaAttributes;

  private roleObserver: MutationObserver;

  private static INACTIVE_TAB_INDEX: number = -1;

  private static ICON_SIZES = {
    s: 16,
    m: 24,
    l: 32,
  };

  @Listen('click', { capture: true })
  onClick(event) {
    if (this.disabled) {
      event.stopPropagation();
    }
    event.preventDefault();
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Space') {
      if (!this.disabled) {
        this.host.dispatchEvent(new window.Event('click'));
      }
      event.preventDefault();
    }
    if (event.code === 'Enter') {
      if (!this.disabled) {
        event.preventDefault();
        this.host.dispatchEvent(new window.Event('click'));
      }
    }
  }

  private getIconName(): string {
    return this.icon.substring(0, this.icon.length - 2) + ButtonGroupButton.ICON_SIZES[this.size];
  }

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.handleHostTabIndex();
    this.initFormsHandling();
  }

  componentDidLoad() {
    this.onCheckedChanged();
    this.groupuiDidLoad.emit();

    this.roleObserver = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'attributes' && mutation.attributeName === 'role') {
          this.onCheckedChanged();
        }
      });
    });

    this.roleObserver.observe(this.host.shadowRoot.querySelector('#button'), {
      attributes: true,
    });
  }

  disconnectedCallback() {
    this.roleObserver?.disconnect();
  }

  @Watch('checked')
  onCheckedChanged() {
    if (this.getRole() && this.getRole() !== 'button') {
      this.host.shadowRoot.querySelector('#button').setAttribute('aria-checked', this.getAriaChecked());
    }
  }

  private initFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      if (this.checked) {
        event.formData.append(this.name, this.value);
      }
    });
  }

  private handleHostTabIndex = () => {
    const tabIndex = this.host.getAttribute('tabIndex');
    if (tabIndex) {
      this.host.removeAttribute('tabIndex');
      this.buttonTabIndex = Number(tabIndex);
    }
  };

  private getRole(): string {
    return this.host.shadowRoot.querySelector('#button')?.getAttribute('role');
  }

  private getAriaChecked(): string {
    return this.checked ? 'true' : 'false';
  }

  render() {
    return (
      <Host>
        <button
          type="button"
          id="button"
          tabIndex={!this.disabled ? this.buttonTabIndex : ButtonGroupButton.INACTIVE_TAB_INDEX}
          {...this.ariaAttributes}
        >
          {this.icon && !this.iconSource && <groupui-icon name={this.getIconName()}></groupui-icon>}
          {this.iconSource && <groupui-icon src={this.iconSource}></groupui-icon>}
          {!this.iconOnly && <slot></slot>}
        </button>
      </Host>
    );
  }
}
